    public override CppString compile()
    {
        ir.fixup_reserved_names();
        if (!options.vulkan_semantics)
        {
            backend.nonuniform_qualifier = "";
            backend.needs_row_major_load_workaround = options.enable_row_major_load_workaround;
        }
        backend.allow_precision_qualifiers = options.vulkan_semantics || options.es;
        backend.force_gl_in_out_block = true;
        backend.supports_extensions = true;
        backend.use_array_constructor = true;
        backend.workgroup_size_is_hidden = true;
        backend.requires_relaxed_precision_analysis = options.es || options.vulkan_semantics;
        backend.support_precise_qualifier = !options.es && options.version >= 400u || options.es && options.version >= 320u;
        backend.constant_null_initializer = "{ }";
        backend.requires_matching_array_initializer = true;
        if (is_legacy_es())
        {
            backend.support_case_fallthrough = false;
        }
        fixup_anonymous_struct_names();
        fixup_type_alias();
        reorder_type_alias();
        build_function_control_flow_graphs_and_analyze();
        find_static_extensions();
        fixup_image_load_store_access();
        update_active_builtins();
        analyze_image_and_sampler_usage();
        analyze_interlocked_resource_usage();
        if (!inout_color_attachments.empty())
        {
            emit_inout_fragment_outputs_copy_to_subpass_inputs();
        }
        if (has_extension(new CppString("GL_EXT_abort")))
        {
            analyze_shader_abort_usage();
        }
        if (unchecked((int)ir.addressing_model) == unchecked((int)Spv.AddressingModel.AddressingModelPhysicalStorageBuffer64))
        {
            analyze_non_block_pointer_types();
        }
        if (Std.find(ir.declared_capabilities.begin(), ir.declared_capabilities.end(), Spv.Capability.CapabilityDescriptorHeapEXT) != ir.declared_capabilities.end())
        {
            analyze_descriptor_heap_types();
        }
        uint pass_count = 0u;
        do
        {
            reset(pass_count);
            buffer.reset();
            emit_header();
            emit_resources();
            emit_extension_workarounds(get_execution_model());
            if (required_polyfills != 0u)
            {
                emit_polyfills(required_polyfills, false);
            }
            if ((options.es || options.vulkan_semantics) && required_polyfills_relaxed != 0u)
            {
                emit_polyfills(required_polyfills_relaxed, true);
            }
            emit_polyfills_integer_dot_product();
            if (ir.is_library_module)
            {
                {
                    foreach (TypedID_TypeFunction export_id in ir.library_exported_functions)
                    {
                        emit_function(get__SPIRFunction(((uint)export_id)), new Bitset());
                    }
                }
            }
            else
            {
                emit_function(get__SPIRFunction(((uint)ir.default_entry_point)), new Bitset());
            }
            pass_count++;
        }
        while (is_forcing_recompilation());
        if (interlocked_is_complex && !ir.is_library_module)
        {
            if (options.use_entry_point_name)
            {
                statement("void ", get_entry_point().name, "()");
            }
            else
            {
                statement("void main()");
            }
            begin_scope();
            statement("// Interlocks were used in a way not compatible with GLSL, this is very slow.");
            statement("SPIRV_Cross_beginInvocationInterlock();");
            statement("spvMainInterlockedBody();");
            statement("SPIRV_Cross_endInvocationInterlock();");
            end_scope();
        }
        if (!options.use_entry_point_name && !ir.is_library_module)
        {
            get_entry_point().name = "main";
        }
        return buffer.str();
    }
