                case unchecked((int)Spv.Op.OpGroupNonUniformIAdd):
                case unchecked((int)Spv.Op.OpGroupNonUniformFAdd):
                case unchecked((int)Spv.Op.OpGroupNonUniformIMul):
                case unchecked((int)Spv.Op.OpGroupNonUniformFMul):
