        }
        clear_force_recompile();
        invalid_expressions.clear();
        composite_insert_overwritten.clear();
        current_function = null;
        expression_usage_counts.clear();
        forwarded_temporaries.clear();
        suppressed_usage_tracking.clear();
        buffer_pointer_variables.clear();
        flushed_phi_variables.clear();
        current_emitting_switch_stack.clear();
        reset_name_caches();
        ir.for_each_typed_id__SPIRFunction_lambda((uint _p, SPIRFunction func) =>
        {
            func.active = false;
            func.flush_undeclared = true;
        });
        ir.for_each_typed_id__SPIRVariable_lambda((uint _p, SPIRVariable @var) =>
        {
            @var.dependees.clear();
        });
        ir.for_each_typed_id__SPIRBlock_lambda((uint _p, SPIRBlock block) =>
        {
            block.rearm_dominated_variables.clear();
        });
        ir.reset_all_of_type__SPIRExpression();
        ir.reset_all_of_type__SPIRAccessChain();
        statement_count = 0u;
        indent = 0u;
        current_loop_level = 0u;
    }
