    public CompilerGLSL.TemporaryCopy handle_instruction_precision(Instruction instruction)
    {
        var ops = stream_mutable(instruction);
        var opcode = unchecked((Spv.Op)instruction.op);
        uint length = instruction.length;
        if (backend.requires_relaxed_precision_analysis)
        {
            if (length > 2u)
            {
                uint forwarding_length = length - 2u;
                if (Globals.opcode_is_precision_sensitive_operation(opcode))
                {
                    analyze_precision_requirements(ops[0], ops[1], ops + 2, forwarding_length);
                }
                else
                if (unchecked((int)opcode) == unchecked((int)Spv.Op.OpExtInst) && length >= 5u && unchecked((int)get__SPIRExtension(ops[2]).ext) == unchecked((int)SPIRExtension.Extension.GLSL))
                {
                    analyze_precision_requirements(ops[0], ops[1], ops + 4, forwarding_length - 2u);
                }
                else
                if (Globals.opcode_is_precision_forwarding_instruction(opcode, ref forwarding_length))
                {
                    forward_relaxed_precision(ops[1], ops + 2, forwarding_length);
                }
            }
            uint result_type = 0u;
            uint result_id = 0u;
            if (Compiler.instruction_to_result_type(ref result_type, ref result_id, opcode, ops, length))
            {
                var itr = temporary_to_mirror_precision_alias.find(ops[1]);
                if (itr != temporary_to_mirror_precision_alias.end())
                {
                    return new CompilerGLSL.TemporaryCopy { dst_id = itr.deref().second, src_id = itr.deref().first };
                }
            }
        }
        return new CompilerGLSL.TemporaryCopy();
    }
    public void emit_block_instructions(SPIRBlock block)
    {
