                        inst.op = unchecked((ushort)Spv.Op.OpCopyObject);
                        inst.length = 3u;
                        inst.ops.push_back(expression_type_id(itr.deref().first));
                        inst.ops.push_back(itr.deref().second);
                        inst.ops.push_back(itr.deref().first);
                        emit_instruction(inst);
