        var lerptype = expression_type(select);
        if (lerptype.vecsize == 1u)
        {
            expr = Std.join(to_enclosed_expression(select, true), " ? ", to_enclosed_pointer_expression(true_value, true), " : ", to_enclosed_pointer_expression(false_value, true));
        }
        else
        {
            var swiz = (uint expression, uint i) =>
            {
                return this.to_extract_component_expression(expression, i);
            };
            expr = type_to_glsl_constructor(restype);
            expr += "(";
            {
                for (uint i = 0u; i < restype.vecsize; i++)
                {
                    expr += swiz(select, i);
                    expr += " ? ";
                    expr += swiz(true_value, i);
                    expr += " : ";
                    expr += swiz(false_value, i);
                    if (i + 1u < restype.vecsize)
