                transposed_type_id = ir.increase_bound_by(1u);
                set__SPIRType_X(transposed_type_id, dummy_type);
            }
            statement(declare_temporary(transposed_type_id, result_id), rhs, ";");
            var e = set__SPIRExpression_X(result_id, to_name(result_id, true), result_type, true);
            e.need_transpose = true;
