    public virtual void replace_illegal_names()
    {
        replace_illegal_names(keywords_static2);
    }
    public void replace_illegal_names(UnorderedSet<CppString> keywords)
    {
        ir.for_each_typed_id__SPIRVariable_lambda((uint _p, SPIRVariable @var) =>
        {
            if (this.is_hidden_variable(@var, false))
            {
                return;
            }
            var meta = this.ir.find_meta(@var.self);
            if (!(meta != null))
            {
                return;
            }
            var m = meta.decoration;
            if (keywords.find(m.alias) != Std.end(keywords))
            {
                m.alias = Std.join("_", m.alias);
            }
        });
        ir.for_each_typed_id__SPIRFunction_lambda((uint _p, SPIRFunction func) =>
        {
            var meta = this.ir.find_meta(func.self);
            if (!(meta != null))
            {
                return;
            }
            var m = meta.decoration;
            if (keywords.find(m.alias) != Std.end(keywords))
            {
                m.alias = Std.join("_", m.alias);
            }
        });
        ir.for_each_typed_id__SPIRType_lambda((uint _p, SPIRType type) =>
        {
            var meta = this.ir.find_meta(type.self);
            if (!(meta != null))
            {
                return;
            }
            var m = meta.decoration;
            if (keywords.find(m.alias) != Std.end(keywords))
            {
                m.alias = Std.join("_", m.alias);
            }
            {
                foreach (Meta.Decoration memb in meta.members)
                {
                    if (keywords.find(memb.alias) != Std.end(keywords))
                    {
                        memb.alias = Std.join("_", memb.alias);
                    }
                }
            }
        });
    }
