    public void replace_fragment_output(SPIRVariable @var)
    {
        ref var m = ref ir.meta[@var.self].decoration;
        uint location = 0u;
        if (m.decoration_flags.get(unchecked((uint)Spv.Decoration.DecorationLocation)))
        {
            location = m.location;
        }
        var type = get__SPIRType(((uint)@var.basetype));
        if (type.array.empty())
        {
            m.alias = Std.join("gl_FragData[", location, "]");
            if (is_legacy_es() && location != 0u)
            {
                require_extension_internal(new CppString("GL_EXT_draw_buffers"));
            }
        }
        else
        if (type.array.size() == 1UL)
        {
            m.alias = "gl_FragData";
            if (location != 0u)
            {
                throw new CompilerError("Arrayed output variable used, but location is not 0. This is unimplemented in SPIRV-Cross.");
            }
            if (is_legacy_es())
            {
                require_extension_internal(new CppString("GL_EXT_draw_buffers"));
            }
        }
        else
        {
            throw new CompilerError("Array-of-array output variable used. This cannot be implemented in legacy GLSL.");
        }
        @var.compat_builtin = true;
    }
    public void replace_fragment_outputs()
    {
        ir.for_each_typed_id__SPIRVariable_lambda((uint _p, SPIRVariable @var) =>
        {
            var type = this.get__SPIRType(((uint)@var.basetype));
            if (!this.is_builtin_variable(@var) && !@var.remapped_variable && type.pointer && unchecked((int)@var.storage) == unchecked((int)Spv.StorageClass.StorageClassOutput))
            {
                this.replace_fragment_output(@var);
            }
        });
    }
    public CppString legacy_tex_op(CppString op, SPIRType imgtype, uint tex)
    {
        string type = default;
        {
            switch (unchecked((int)imgtype.image.dim))
            {
                case unchecked((int)Spv.Dim.Dim1D):
                {
                    if (options.es)
                    {
                        type = imgtype.image.arrayed && !options.es ? "2DArray" : "2D";
                    }
                    else
                    {
                        type = imgtype.image.arrayed && !options.es ? "1DArray" : "1D";
                    }
                    break;
                }
                case unchecked((int)Spv.Dim.Dim2D):
                {
                    type = imgtype.image.arrayed && !options.es ? "2DArray" : "2D";
                    break;
                }
                case unchecked((int)Spv.Dim.Dim3D):
                {
                    type = "3D";
                    break;
                }
                case unchecked((int)Spv.Dim.DimCube):
                {
                    type = "Cube";
                    break;
                }
                case unchecked((int)Spv.Dim.DimRect):
                {
                    type = "2DRect";
                    break;
                }
                case unchecked((int)Spv.Dim.DimBuffer):
                {
                    type = "Buffer";
                    break;
                }
                case unchecked((int)Spv.Dim.DimSubpassData):
                {
                    type = "2D";
                    break;
                }
                default:
                {
                    type = "";
                    break;
                }
            }
        }
        bool legacy_lod_ext = false;
        var execution = get_entry_point();
        if (op == "textureGrad" || op == "textureProjGrad" || (op == "textureLod" || op == "textureProjLod") && unchecked((int)execution.model) != unchecked((int)Spv.ExecutionModel.ExecutionModelVertex))
        {
            if (is_legacy_es())
            {
                legacy_lod_ext = true;
                require_extension_internal(new CppString("GL_EXT_shader_texture_lod"));
            }
            else
            if (is_legacy_desktop())
            {
                require_extension_internal(new CppString("GL_ARB_shader_texture_lod"));
            }
        }
        if (op == "textureLodOffset" || op == "textureProjLodOffset")
        {
            if (is_legacy_es())
            {
                throw new CompilerError(Std.join(op, " not allowed in legacy ES"));
            }
            require_extension_internal(new CppString("GL_EXT_gpu_shader4"));
        }
        bool is_comparison = is_depth_image(imgtype, tex);
        if (is_comparison && is_legacy_es())
        {
            if (op == "texture" || op == "textureProj")
            {
                require_extension_internal(new CppString("GL_EXT_shadow_samplers"));
            }
            else
            {
                throw new CompilerError(Std.join(op, " not allowed on depth samplers in legacy ES"));
            }
            if (unchecked((int)imgtype.image.dim) == unchecked((int)Spv.Dim.DimCube))
            {
                return new CppString("shadowCubeNV");
            }
        }
        if (op == "textureSize")
        {
            if (is_legacy_es())
            {
                throw new CompilerError("textureSize not supported in legacy ES");
            }
            if (is_comparison)
            {
                throw new CompilerError("textureSize not supported on shadow sampler in legacy GLSL");
            }
            require_extension_internal(new CppString("GL_EXT_gpu_shader4"));
        }
        if (op == "texelFetch" && is_legacy_es())
        {
            throw new CompilerError("texelFetch not supported in legacy ES");
        }
        bool is_es_and_depth = is_legacy_es() && is_comparison;
        CppString type_prefix = new CppString(is_comparison ? "shadow" : "texture");
        if (op == "texture")
        {
            return is_es_and_depth ? Std.join(type_prefix, type, "EXT") : Std.join(type_prefix, type);
        }
        else
        if (op == "textureLod")
        {
            return Std.join(type_prefix, type, legacy_lod_ext ? "LodEXT" : "Lod");
        }
        else
        if (op == "textureProj")
        {
            return Std.join(type_prefix, type, is_es_and_depth ? "ProjEXT" : "Proj");
        }
        else
        if (op == "textureGrad")
        {
            return Std.join(type_prefix, type, is_legacy_es() ? "GradEXT" : is_legacy_desktop() ? "GradARB" : "Grad");
        }
        else
        if (op == "textureProjLod")
        {
            return Std.join(type_prefix, type, legacy_lod_ext ? "ProjLodEXT" : "ProjLod");
        }
        else
        if (op == "textureLodOffset")
        {
            return Std.join(type_prefix, type, "LodOffset");
        }
        else
        if (op == "textureProjGrad")
        {
            return Std.join(type_prefix, type, is_legacy_es() ? "ProjGradEXT" : is_legacy_desktop() ? "ProjGradARB" : "ProjGrad");
        }
        else
        if (op == "textureProjLodOffset")
        {
            return Std.join(type_prefix, type, "ProjLodOffset");
        }
        else
        if (op == "textureSize")
        {
            return Std.join("textureSize", type);
        }
        else
        if (op == "texelFetch")
        {
            return Std.join("texelFetch", type);
        }
        else
        {
            throw new CompilerError(Std.join("Unsupported legacy texture op: ", op));
        }
    }
    public void forward_relaxed_precision(uint dst_id, Ptr<uint> args, uint length)
    {
        if (!backend.requires_relaxed_precision_analysis)
        {
            return;
        }
        var input_precision = analyze_expression_precision(args, length);
        if (unchecked((int)input_precision) == unchecked((int)CompilerGLSL.Options.Precision.Mediump))
        {
            set_decoration(new TypedID_TypeNone(dst_id), Spv.Decoration.DecorationRelaxedPrecision, 0u);
        }
    }
    public void analyze_precision_requirements(uint type_id, uint dst_id, Ptr<uint> args, uint length)
    {
        if (!backend.requires_relaxed_precision_analysis)
        {
            return;
        }
        var type = get__SPIRType(type_id);
        if (unchecked((int)type.basetype) != unchecked((int)SPIRType.BaseType.Float) && unchecked((int)type.basetype) != unchecked((int)SPIRType.BaseType.Int) && unchecked((int)type.basetype) != unchecked((int)SPIRType.BaseType.UInt))
        {
            return;
        }
        bool operation_is_highp = !has_decoration(new TypedID_TypeNone(dst_id), Spv.Decoration.DecorationRelaxedPrecision);
        var input_precision = analyze_expression_precision(args, length);
        if (unchecked((int)input_precision) == unchecked((int)CompilerGLSL.Options.Precision.DontCare))
        {
            consume_temporary_in_precision_context(type_id, dst_id, input_precision);
            return;
        }
        if (operation_is_highp && unchecked((int)input_precision) == unchecked((int)CompilerGLSL.Options.Precision.Mediump) || !operation_is_highp && unchecked((int)input_precision) == unchecked((int)CompilerGLSL.Options.Precision.Highp))
        {
            var precision = operation_is_highp ? CompilerGLSL.Options.Precision.Highp : CompilerGLSL.Options.Precision.Mediump;
            {
                for (uint i = 0u; i < length; i++)
                {
                    args[i] = consume_temporary_in_precision_context(expression_type_id(args[i]), args[i], precision);
                }
            }
        }
    }
    public CompilerGLSL.Options.Precision analyze_expression_precision(Ptr<uint> args, uint length)
    {
        bool expression_has_highp = false;
        bool expression_has_mediump = false;
        {
            for (uint i = 0u; i < length; i++)
            {
                uint arg = args[i];
                var handle_type = ir.ids[unchecked((ulong)arg)].get_type();
                if (unchecked((int)handle_type) == unchecked((int)Types.TypeConstant) || unchecked((int)handle_type) == unchecked((int)Types.TypeConstantOp) || unchecked((int)handle_type) == unchecked((int)Types.TypeUndef))
                {
                    continue;
                }
                if (has_decoration(new TypedID_TypeNone(arg), Spv.Decoration.DecorationRelaxedPrecision))
                {
                    expression_has_mediump = true;
                }
                else
                {
                    expression_has_highp = true;
                }
            }
        }
        if (expression_has_highp)
        {
            return CompilerGLSL.Options.Precision.Highp;
        }
        else
        if (expression_has_mediump)
        {
            return CompilerGLSL.Options.Precision.Mediump;
        }
        else
        {
            return CompilerGLSL.Options.Precision.DontCare;
        }
    }
