    public UnorderedSet<uint> emitted_functions = new UnorderedSet<uint>();
    public UnorderedSet<uint> flushed_phi_variables = new UnorderedSet<uint>();
    public UnorderedSet<uint> flattened_buffer_blocks = new UnorderedSet<uint>();
