    public CompilerGLSL.ShaderSubgroupSupportHelper shader_subgroup_supporter = new CompilerGLSL.ShaderSubgroupSupportHelper();
    public CppString load_flattened_struct(CppString basename, SPIRType type)
    {
        var expr = type_to_glsl_constructor(type);
        expr += '(';
        {
            for (uint i = 0u; i < unchecked((uint)type.member_types.size()); i++)
            {
                if (i != 0u)
                {
                    expr += ", ";
                }
                var member_type = get__SPIRType(((uint)type.member_types[unchecked((ulong)i)]));
                if (unchecked((int)member_type.basetype) == unchecked((int)SPIRType.BaseType.Struct))
                {
                    expr += load_flattened_struct(to_flattened_struct_member(basename, type, i), member_type);
                }
                else
                {
                    expr += to_flattened_struct_member(basename, type, i);
                }
            }
        }
        expr += ')';
        return expr;
    }
    public CppString to_flattened_struct_member(CppString basename, SPIRType type, uint index)
    {
        var ret = Std.join(basename, "_", to_member_name(type, index));
        ParsedIR.sanitize_underscores(ref ret);
        return ret;
    }
    public void store_flattened_struct(uint lhs_id, uint value)
    {
        var type = expression_type(lhs_id);
        var basename = to_flattened_access_chain_expression(lhs_id);
        store_flattened_struct(basename, value, type, new CppVector<uint>());
    }
    public void store_flattened_struct(CppString basename, uint rhs_id, SPIRType type, CppVector<uint> indices)
    {
        CppVector<uint> sub_indices = indices.Clone();
        sub_indices.push_back(0u);
        var member_type = type;
        {
            foreach (uint index in indices)
            {
                member_type = get__SPIRType(((uint)member_type.member_types[unchecked((ulong)index)]));
            }
        }
        {
            for (uint i = 0u; i < unchecked((uint)member_type.member_types.size()); i++)
            {
                sub_indices.back() = i;
