    public UnorderedMap<uint, uint> expression_usage_counts = new UnorderedMap<uint, uint>();
    public void track_expression_read(uint id)
    {
        {
            switch (unchecked((int)ir.ids[unchecked((ulong)id)].get_type()))
            {
                case unchecked((int)Types.TypeExpression):
                {
                    {
                        var e = get__SPIRExpression(id);
                        {
                            foreach (TypedID_TypeNone implied_read in e.implied_read_expressions)
                            {
                                track_expression_read(((uint)implied_read));
                            }
                        }
                        break;
                    }
                }
                case unchecked((int)Types.TypeAccessChain):
                {
                    {
                        var e = get__SPIRAccessChain(id);
                        {
                            foreach (TypedID_TypeNone implied_read in e.implied_read_expressions)
                            {
                                track_expression_read(((uint)implied_read));
                            }
                        }
                        break;
                    }
                }
                default:
                {
                    break;
                }
            }
        }
        if (expression_is_forwarded(id) && !expression_suppresses_usage_tracking(id))
        {
            ref var v = ref expression_usage_counts[id];
            v++;
            if (expression_read_implies_multiple_reads(id))
