    public void rewrite_load_for_wrapped_row_major(ref CppString expr, TypedID_TypeType loaded_type, TypedID_TypeNone ptr)
    {
        var @var = maybe_get_backing_variable(((uint)ptr));
        if (!(@var != null))
        {
            return;
        }
        var backing_type = get__SPIRType(((uint)@var.basetype));
        bool is_ubo = unchecked((int)backing_type.basetype) == unchecked((int)SPIRType.BaseType.Struct) && unchecked((int)backing_type.storage) == unchecked((int)Spv.StorageClass.StorageClassUniform) && has_decoration(backing_type.self, Spv.Decoration.DecorationBlock);
