                    }
                    if (!decorations.get(unchecked((uint)Spv.Decoration.DecorationRelaxedPrecision)))
                    {
                        relaxed = false;
                    }
                }
            }
        }
        if (rewrite)
        {
            request_workaround_wrapper_overload(loaded_type);
            expr = Std.join("spvWorkaroundRowMajor", relaxed ? "MP" : "", "(", expr, ")");
        }
    }
