    public CppVector<CompilerGLSL.IntegerDotProduct> integer_dot_products_polyfills = new CppVector<CompilerGLSL.IntegerDotProduct>();
    public void add_integer_dot_product_polyfill(CompilerGLSL.IntegerDotProduct idot)
    {
        {
            foreach (CompilerGLSL.IntegerDotProduct impl in integer_dot_products_polyfills)
            {
                if (impl.result_type == idot.result_type && impl.argument_type[0] == idot.argument_type[0] && impl.argument_type[1] == idot.argument_type[1] && unchecked((int)impl.op) == unchecked((int)idot.op))
                {
                    return;
                }
            }
