    public CppString integer_dot_product_entry_point(CompilerGLSL.IntegerDotProduct idot)
    {
        CppString expr = new CppString("spv");
        {
            switch (unchecked((int)idot.op))
            {
                case unchecked((int)Spv.Op.OpSDot):
                {
                    expr += "SDot";
                    break;
                }
                case unchecked((int)Spv.Op.OpUDot):
                {
                    expr += "UDot";
                    break;
                }
                case unchecked((int)Spv.Op.OpSUDot):
                {
                    expr += "SUDot";
                    break;
                }
                case unchecked((int)Spv.Op.OpSDotAccSat):
                {
                    expr += "SDotAccSat";
                    break;
                }
                case unchecked((int)Spv.Op.OpUDotAccSat):
                {
                    expr += "UDotAccSat";
                    break;
                }
                case unchecked((int)Spv.Op.OpSUDotAccSat):
                {
                    expr += "SUDotAccSat";
                    break;
                }
                default:
                {
                    throw new CompilerError("Invalid integer dot product opcode.");
                }
            }
        }
        expr += "_" + type_to_glsl(get__SPIRType(idot.result_type), 0u);
        {
            foreach (uint arg in idot.argument_type)
            {
                expr += "_" + type_to_glsl(get__SPIRType(arg), 0u);
            }
        }
        return expr;
    }
    public void emit_polyfills_integer_dot_product()
    {
        {
            foreach (CompilerGLSL.IntegerDotProduct op in integer_dot_products_polyfills)
            {
                CppString caps = Std.join("[", (int)Spv.Capability.CapabilityDotProduct);
                var arg_type = get__SPIRType(op.argument_type[0]);
                if (unchecked((int)arg_type.basetype) == unchecked((int)SPIRType.BaseType.SByte) || unchecked((int)arg_type.basetype) == unchecked((int)SPIRType.BaseType.UByte))
                {
                    caps += Std.join(", ", (int)Spv.Capability.CapabilityDotProductInput4x8Bit);
                }
                else
                if (arg_type.vecsize == 1u)
                {
                    caps += Std.join(", ", (int)Spv.Capability.CapabilityDotProductInput4x8BitPacked);
                }
                else
                {
                    caps += Std.join(", ", (int)Spv.Capability.CapabilityDotProductInputAll);
                }
                caps += "]";
                var arg0 = type_to_glsl(get__SPIRType(op.argument_type[0]), 0u);
                var arg1 = type_to_glsl(get__SPIRType(op.argument_type[1]), 0u);
                var acc_arg = unchecked((int)op.op) == unchecked((int)Spv.Op.OpSDotAccSat) || unchecked((int)op.op) == unchecked((int)Spv.Op.OpUDotAccSat) || unchecked((int)op.op) == unchecked((int)Spv.Op.OpSUDotAccSat) ? ", " + type_to_glsl(get__SPIRType(op.result_type), 0u) : new CppString("");
                bool packed_vector = get__SPIRType(op.argument_type[0]).vecsize == 1u;
                string packed_argument = packed_vector ? ", spirv_literal uint packedFormat" : "";
                statement("spirv_instruction (extensions = [\"SPV_KHR_integer_dot_product\"], capabilities = ", caps, ", id = ", (int)op.op, ")");
                statement(type_to_glsl(get__SPIRType(op.result_type), 0u), " ", integer_dot_product_entry_point(op), "(", arg0, " arg0, ", arg1, " arg1", acc_arg, packed_argument, ");");
                statement("");
            }
        }
    }
