    public bool args_will_forward(uint id, Ptr<uint> args, uint num_args, bool pure)
    {
        if (forced_temporaries.find(id) != Std.end(forced_temporaries))
        {
            return false;
        }
        {
            for (uint i = 0u; i < num_args; i++)
            {
                if (!should_forward(args[i]))
                {
                    return false;
                }
            }
        }
        if (!pure)
        {
            {
                foreach (uint global in global_variables)
                {
                    if (!should_forward(global))
                    {
                        return false;
                    }
                }
            }
            {
                foreach (uint aliased in aliased_variables)
                {
                    if (!should_forward(aliased))
                    {
                        return false;
                    }
                }
            }
        }
        return true;
    }
