            type.vecsize = vecsize;
        }
        return Std.join(Globals.to_pls_layout(@var.format), to_pls_qualifiers_glsl(variable), type_to_glsl(type, 0u), " ", to_name(((uint)variable.self), true));
    }
    public string to_pls_qualifiers_glsl(SPIRVariable variable)
