    public void emit_pls()
    {
        var execution = get_entry_point();
        if (unchecked((int)execution.model) != unchecked((int)Spv.ExecutionModel.ExecutionModelFragment))
        {
            throw new CompilerError("Pixel local storage only supported in fragment shaders.");
        }
        if (!options.es)
        {
            throw new CompilerError("Pixel local storage only supported in OpenGL ES.");
        }
        if (options.version < 300u)
        {
            throw new CompilerError("Pixel local storage only supported in ESSL 3.0 and above.");
        }
        if (!pls_inputs.empty())
        {
            statement("__pixel_local_inEXT _PLSIn");
            begin_scope();
            {
                foreach (PlsRemap input in pls_inputs)
                {
                    statement(pls_decl(input), ";");
                }
            }
            end_scope_decl();
            statement("");
        }
        if (!pls_outputs.empty())
        {
            statement("__pixel_local_outEXT _PLSOut");
            begin_scope();
            {
                foreach (PlsRemap output in pls_outputs)
                {
                    statement(pls_decl(output), ";");
                }
            }
            end_scope_decl();
            statement("");
        }
    }
    public void remap_pls_variables()
